//! One valid RSASSA-PKCS1-v1_5 SHA-256 signature for each key size, from Wycheproof's
//! `testvectors_v1/rsa_signature_2048_sha256_test.json` and `rsa_signature_4096_sha256_test.json`, test group 0,
//! tcId 2, read on 2026-10-21. Each key's public exponent is 65537, and each message is 20 zero bytes. The
//! moduli drop Wycheproof's leading zero byte.

use hex_literal::hex;

/// The signed message of both vectors.
pub const MESSAGE: [u8; 20] = [0; 20];

/// The 2048-bit modulus, big-endian.
pub const MODULUS_2048: [u8; 256] = hex!(
    ""
);

/// The signature of [`MESSAGE`] under the 2048-bit key, big-endian.
pub const SIGNATURE_2048: [u8; 256] = hex!(
    ""
);

/// The 4096-bit modulus, big-endian.
pub const MODULUS_4096: [u8; 512] = hex!(
    ""
);

/// The signature of [`MESSAGE`] under the 4096-bit key, big-endian.
pub const SIGNATURE_4096: [u8; 512] = hex!(
    ""
);
